"use client";

import { useState } from "react";
import { smartRevisionPlanner, type SmartRevisionPlannerOutput } from "@/ai/flows/smart-revision-planner";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Lightbulb, BookCheck, AlertTriangle, Loader2 } from "lucide-react";

async function getRevisionPlan() {
  "use server";
  try {
    const mockBrainMap = JSON.stringify({
      topics: [
        { name: "Algebra", progress: 0.8, lastRevised: "2024-05-01" },
        { name: "Calculus", progress: 0.4, lastRevised: "2024-05-20" },
        { name: "Photosynthesis", progress: 0.9, lastRevised: "2024-04-15" },
        { name: "Newton's Laws", progress: 0.6, lastRevised: "2024-05-25" },
      ],
    });

    return await smartRevisionPlanner({
      brainMap: mockBrainMap,
      studentId: "user-123",
    });
  } catch (error) {
    console.error(error);
    return null;
  }
}

export default function PlannerPage() {
  const [plan, setPlan] = useState<SmartRevisionPlannerOutput | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGeneratePlan = async () => {
    setLoading(true);
    setError(null);
    setPlan(null);
    const result = await getRevisionPlan();
    if (result) {
      setPlan(result);
    } else {
      setError("Failed to generate a revision plan. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold font-headline">Smart Revision Planner</h1>
        <p className="text-muted-foreground">
          Your AI-powered daily list of revision tasks based on spaced repetition.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Today's Plan</CardTitle>
          <CardDescription>Click the button below to generate a personalized study plan for today.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button onClick={handleGeneratePlan} disabled={loading}>
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              "Generate Today's Plan"
            )}
          </Button>
        </CardContent>
      </Card>

      {error && (
         <Card className="border-destructive">
            <CardHeader className="flex flex-row items-center gap-4">
                <AlertTriangle className="h-8 w-8 text-destructive" />
                <div>
                    <CardTitle className="text-destructive">An Error Occurred</CardTitle>
                    <CardDescription>{error}</CardDescription>
                </div>
            </CardHeader>
        </Card>
      )}

      {plan && plan.revisionList.length > 0 && (
        <div className="space-y-4">
          <h2 className="text-2xl font-semibold font-headline">Your Revision Tasks</h2>
          <ul className="space-y-4">
            {plan.revisionList.map((task, index) => (
              <li key={index}>
                <Card className="hover:border-primary transition-colors">
                  <CardHeader className="flex flex-row items-start justify-between">
                    <div>
                      <CardTitle>{task.topic}</CardTitle>
                      <CardDescription className="flex items-center gap-2 mt-1">
                        <Lightbulb className="w-4 h-4 text-amber-500" />
                        <span>{task.reason}</span>
                      </CardDescription>
                    </div>
                    <Button size="sm" variant="outline">
                      <BookCheck className="mr-2 h-4 w-4" />
                      Revise Now
                    </Button>
                  </CardHeader>
                </Card>
              </li>
            ))}
          </ul>
        </div>
      )}
       {plan && plan.revisionList.length === 0 && (
         <Card>
            <CardHeader>
                <CardTitle>All Caught Up!</CardTitle>
                <CardDescription>No priority revisions for today. Feel free to explore new topics!</CardDescription>
            </CardHeader>
        </Card>
      )}
    </div>
  );
}
